<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import {ReceiptText,ArrowDownLeft,ArrowUpRight,Download,Search,RefreshCw} from '@lucide/vue'
import type {ApiResult,Player} from '../types'
import type {FinanceEntry,FinanceLedger as LedgerSummary} from '../living-types'
import content from '../content.json'
const props=defineProps<{player:Player;busy:boolean;perform:(a:string,p?:Record<string,unknown>)=>Promise<ApiResult|undefined>}>()
const category=ref('all'),direction=ref('all'),from=ref(''),to=ref(''),rows=ref<FinanceEntry[]>([]),cursor=ref<number|null>(null),fetching=ref(false),message=ref(''),loaded=ref(false)
const remoteSummary=ref<LedgerSummary|null>(null)
const summary=computed(()=>remoteSummary.value||props.player.ledger)
const money=(n:number)=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:6}).format(n)
function params(before?:number){return{category:category.value,direction:direction.value,from:from.value?new Date(from.value+'T00:00:00').getTime():0,to:to.value?new Date(to.value+'T23:59:59.999').getTime():8640000000000000,...(before?{before}:{})}}
async function load(more=false){if(fetching.value)return;fetching.value=true;message.value='';try{const r=await props.perform('ledger_list',params(more?cursor.value||undefined:undefined));if(r?.ledger){remoteSummary.value=r.ledger.summary||props.player.ledger;rows.value=more?[...rows.value,...r.ledger.entries]:r.ledger.entries;cursor.value=r.ledger.next;loaded.value=true;if(!rows.value.length)message.value='这个筛选范围暂时没有实际收支。'}else if(!r)message.value='未读取完成，可以稍后重试。'}finally{fetching.value=false}}
const pageNet=computed(()=>rows.value.reduce((n,r)=>n+r.amount,0))
async function download(){if(fetching.value)return;fetching.value=true;message.value='正在整理筛选范围内的全部明细…';try{let all:FinanceEntry[]=[],next:number|undefined;do{const r=await props.perform('ledger_list',params(next));if(!r?.ledger){message.value='导出尚未完成，请重试。';return}all.push(...r.ledger.entries);next=r.ledger.next||undefined;}while(next);const escape=(v:unknown)=>{const text=String(v??'');return '"'+(typeof v==='string'&&/^[s]*[=+@-]/.test(text)?"'"+text:text).replaceAll('"','""')+'"'};const lines=[['时间','收入/支出','金额','来源','分类','变动后余额'],...all.map(r=>[new Date(r.at).toLocaleString('zh-CN'),r.amount>0?'收入':'支出',r.amount,r.title,(content.financeCategories as Record<string,string>)[r.category],r.balance])];const url=URL.createObjectURL(new Blob(['\uFEFF'+lines.map(a=>a.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=props.player.name+'-经费收支明细.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message.value='已导出 '+all.length+' 笔实际收支。'}finally{fetching.value=false}}
onMounted(()=>load())
</script>
<template><section class="finance-detail"><header class="v8-heading"><ReceiptText :size="28"/><div><span class="small-label">EVERY LITTLE FUND · 每一笔都有来处</span><h2>我的经费明细</h2><p>从 {{ new Date(summary.openedAt).toLocaleDateString('zh-CN') }} 开始记录。此前余额作为期初，不补造历史。</p></div></header><div class="finance-totals"><div><small>本次查询余额</small><b>{{ money(summary.balance) }}</b></div><div><small>累计收入</small><b class="income">+{{ money(summary.income) }}</b></div><div><small>累计支出</small><b class="expense">−{{ money(summary.expense) }}</b></div></div><p class="v8-muted">期初 {{ money(summary.openingBalance) }} + 收入 {{ money(summary.income) }} − 支出 {{ money(summary.expense) }} = 查询时余额。等待中的预算、未领取收益不计为实际到账。</p>
 <form class="finance-filters" @submit.prevent="load()"><label>收支<select v-model="direction"><option value="all">全部收支</option><option value="income">只看收入</option><option value="expense">只看支出</option></select></label><label>来源分类<select v-model="category"><option value="all">全部来源</option><option v-for="(name,id) in content.financeCategories" :key="id" :value="id">{{ name }}</option></select></label><label>开始日期<input v-model="from" type="date"/></label><label>结束日期<input v-model="to" type="date"/></label><button class="primary" :disabled="busy||fetching"><Search :size="15"/>筛选明细</button><button type="button" class="secondary" :disabled="busy||fetching" @click="download"><Download :size="15"/>导出全部筛选结果</button></form>
 <div class="section-title"><h2>实际收支流水</h2><span>{{ rows.length }} 笔已显示 · 合计 {{ money(pageNet) }}</span></div><p v-if="message" class="v8-muted" role="status">{{ message }}</p><p v-if="fetching&&!loaded" class="empty-note">正在读取自己的云端账本…</p><ol class="finance-rows"><li v-for="r in rows" :key="r.id"><span class="finance-direction" :class="r.amount>0?'income':'expense'"><component :is="r.amount>0?ArrowDownLeft:ArrowUpRight" :size="19"/></span><div><h3>{{ r.title }}</h3><p>{{ (content.financeCategories as Record<string,string>)[r.category] }} · {{ new Date(r.at).toLocaleString('zh-CN') }}</p><small>结算后余额 {{ money(r.balance) }}</small></div><b :class="r.amount>0?'income':'expense'">{{ r.amount>0?'+':'' }}{{ money(r.amount) }}</b></li></ol><button v-if="cursor" class="secondary wide" :disabled="busy||fetching" @click="load(true)"><RefreshCw :size="15"/>继续读取更早明细</button><p class="gentle-footer">只有自己可以查询和导出自己的账本。重试已完成的操作不会重复扣款或重复记账。</p></section></template>
